@pytest.mark.detective
def test_study_extract_value_3():
    """VALUE survivor — distinguishing witness (original raises KeyError: 'coordinates')."""
    try:
        _result = study_extract(
            study={},
            view={
                "nct": "x",
                "coverage": "x",
                "criteria": "x",
                "outcomes": "x",
                "hasResults": "x",
                "digest": "x",
            },
            tiers={
                "nct": "x",
                "coverage": "x",
                "criteria": "x",
                "outcomes": "x",
                "hasResults": "x",
                "digest": "x",
            },
        )
    except KeyError as _exc:
        assert str(_exc) == "'coordinates'"
    except BaseException as _exc:
        pytest.fail(f"expected KeyError, got {type(_exc).__name__}: {_exc!r}")
    else:
        pytest.fail(f"expected KeyError, but the call returned {_result!r}")


